/// <summary>
/// MPJ_3535_MetPayVendorFinancing 03/25/2021
/// Fills in the vend account num
/// </summary>
/// <param name="sender">Form Data Source</param>
/// <param name="e">Form data source event</param>
[
    FormDataSourceEventHandler(formDataSourceStr(VendTable, metVendTable), FormDataSourceEventType::ValidatingWrite),
    SuppressBPWarningAttribute('BPParameterNotUsed', 'Parameter required by the event interface')
]
public static void METVendTable_OnValidatingWrite(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormRun                 form            = sender.formRun();
    FormDataSource          vendTable_ds    = form.dataSource(formDataSourceStr(VendTable, VendTable)) as FormDataSource;
    FormDataSource          metVendTable_ds = form.dataSource(formDataSourceStr(VendTable, metVendTable)) as FormDataSource;
    METVendTable            metVendTable    = metVendTable_ds.cursor();
    VendTable               vendTable       = vendTable_ds.cursor();
    
    metVendTable.AccountNum = vendTable.AccountNum;
}

    /// <summary>
    /// MPJ_21178_VendorGlobal on 16 Mar 2022 by chaminda
    /// </summary>
    /// <param name="sender"> Get form data source object</param>
    /// <param name="e"> Get form data source args</param>
    [FormDataSourceEventHandler(formDataSourceStr(VendTable, METVendTable), FormDataSourceEventType::Activated),
     SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")
    ]
    public static void METVendTable_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
    {
        if(!Global::isSystemAdministrator())
        {
            METVendParameters   metVendParameters= METVendParameters::find();                
            sender.object(fieldNum(METVendTable,VendLegalEntityID)).enabled(!metVendParameters.MDMGlobalVendorMasterNoneEditable);
            sender.object(fieldNum(METVendTable,VendStatus)).enabled(!metVendParameters.MDMGlobalVendorMasterNoneEditable);
            sender.object(fieldNum(METVendTable,VendStatusChangeDate)).enabled(!metVendParameters.MDMGlobalVendorMasterNoneEditable);
            sender.object(fieldNum(METVendTable,VendPrivateLabel)).enabled(!metVendParameters.MDMGlobalVendorMasterNoneEditable);
            sender.object(fieldNum(METVendTable,VendStateNationalSupplierSetting)).enabled(!metVendParameters.MDMGlobalVendorMasterNoneEditable);
            sender.object(fieldNum(METVendTable,VendDistributionMethod)).enabled(!metVendParameters.MDMGlobalVendorMasterNoneEditable);
        }

        // MPJ_21178_VendorGlobal on 07 Apr 2022 by chaminda
        // Disable vendor legal entity if vendor account matches to invoice account.
        VendTable           vendTable       = sender.formRun().dataSource().cursor();
        VendInvoiceAccount  invoiceAccount  = sender.formRun().dataSource().object(fieldNum(VendTable, InvoiceAccount)).getValue();
        if(invoiceAccount && (vendTable.AccountNum == invoiceAccount))
        {
            sender.object(fieldNum(METVendTable,VendLegalEntityID )).enabled(false);
        }
        else
        {
            sender.object(fieldNum(METVendTable,VendLegalEntityID )).enabled(true);
        }
    }

/// <summary>
/// MPJ_21178_VendorGlobal on 17 Mar 2022 by chaminda
/// </summary>
/// <param name="sender"> Get form data source object</param>
/// <param name="e"> Get form data source args</param>
[FormDataFieldEventHandler(formDataFieldStr(VendTable, METVendTable, VendStatus), FormDataFieldEventType::Modified),
 SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")
]
public static void VendStatus_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    sender.datasource().object(fieldNum(METVendTable, VendStatusChangeDate)).setValue(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()));
}

    /// <summary>
    /// MPJ_21178_VendorGlobal on 17 Mar 2022 by chaminda
    /// </summary>
    /// <param name="sender"> Get form control object</param>
    /// <param name="e"> Get form data source args</param>
    [FormControlEventHandler(formControlStr(VendTable, METVendTable_VendDistributionMethod), FormControlEventType::Lookup),
     SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")
    ]
    public static void METVendTable_VendDistributionMethod_OnLookup(FormControl sender, FormControlEventArgs e)
    {
        //Changed on 04/04/2022 to use builder class.
        SysDictEnum                         sysDictEnum = new SysDictEnum(enumNum(METVendDistributionMethod));
        FormControlCancelableSuperEventArgs event       = e as FormControlCancelableSuperEventArgs;
        FormStringControl                   formStringControl = sender.formRun().design().controlName(formControlStr(VendTable, METVendTable_VendDistributionMethod));
        FormDataSource metVendTable_ds =sender.formRun().dataSource(formDataSourceStr(VendTable, METVendTable));

        METMultiSelectLookupBuilder metMultiSelectLookupBuilder = new METMultiSelectLookupBuilder();
        metMultiSelectLookupBuilder.buildLookup(sender,e,metVendTable_ds,formStringControl,sysDictEnum.id());
        
        
    }

/// <summary>
/// The vendor site settings button click event handler
/// </summary>
/// <param name="sender">Get form control object</param>
/// <param name="e">Get form data source args</param>
[FormControlEventHandler(formControlStr(VendTable, METVendSiteSettings), FormControlEventType::Clicked)]
public static void METVendSiteSettings_OnClicked(FormControl sender, FormControlEventArgs e)
{      
    FormRun formRun = sender.formRun();
    FormDataSource formDataSource = formRun.dataSource("VendTable");
    VendTable vendTable = formDataSource.cursor();
    Args args = new Args();
    args.record(vendTable);
    args.caller(formRun);
    
    if (!vendTable.InvoiceAccount)
    {
        if (Box::yesNo("@MET:METVendSiteInvAccWarning", DialogButton::No) == DialogButton::Yes)
        {
            new MenuFunction(menuItemDisplayStr(METVendSiteSettingsSetup), MenuItemType::Display).run(args);
        }
    }
    else
    {
        new MenuFunction(menuItemDisplayStr(METVendSiteSettingsSetup), MenuItemType::Display).run(args);
    }
}

    /// <summary>
    /// MPJ_21178_VendorGlobal by kavya - 4/5/2022
    /// To open vendor parent leagal entity form 
    /// </summary>
    /// <param name="sender">sendor information</param>
    /// <param name="e">arguements</param>
    [FormControlEventHandler(formControlStr(VendTable, METVendParentCompanyLegalEntity), FormControlEventType::Clicked),
      SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void METVendParentCompanyLegalEntity_OnClicked(FormControl sender, FormControlEventArgs e)
    {
        FormRun formRun;
        Form formToCall = new Form(formstr(METVendParentCompanyLegalEntity));

        Args args = new Args();

        ;
        args.object(formToCall);

        formRun = ClassFactory.formRunClass(args);
        formRun.init();
        formRun.run();
        formRun.wait();
    }
